import{_ as t,o as d,c as r,a2 as n}from"./chunks/framework.D-e0yUf_.js";const u=JSON.parse('{"title":"Anhang: Symptome und typische Ursachen","description":"","frontmatter":{},"headers":[],"relativePath":"anhang-symptome.md","filePath":"anhang-symptome.md"}'),i={name:"anhang-symptome.md"};function a(o,e,s,c,h,l){return d(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="anhang-symptome-und-typische-ursachen" tabindex="-1">Anhang: Symptome und typische Ursachen <a class="header-anchor" href="#anhang-symptome-und-typische-ursachen" aria-label="Permalink to &quot;Anhang: Symptome und typische Ursachen&quot;">​</a></h1><p>Nachschlagetabelle für die Fehlersuche in Kubernetes und OpenShift. Die Spalte „Prüfen“ nennt die Ansicht oder den Befehl, in dem die Ursache meist sichtbar wird. <code>oc</code> und <code>kubectl</code> sind dabei austauschbar.</p><h2 id="pods" tabindex="-1">Pods <a class="header-anchor" href="#pods" aria-label="Permalink to &quot;Pods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Typische Ursachen</th><th>Prüfen</th></tr></thead><tbody><tr><td>Pod <code>Pending</code></td><td>nicht genug CPU oder Speicher auf den Nodes; Volume nicht verfügbar; Node-Auswahl (Selector, Taints) passt nicht</td><td>Events des Pods</td></tr><tr><td>Weniger Pods als gewünscht, kein Fehler am Pod</td><td>Quota überschritten; Richtlinie lehnt Pod ab</td><td>Events des ReplicaSets bzw. des Namespace; <code>oc describe quota</code></td></tr><tr><td><code>ErrImagePull</code>, <code>ImagePullBackOff</code> mit „not found“ / „manifest unknown“</td><td>Tag oder Image-Name falsch; Tag in der Registry gelöscht</td><td>Events des Pods; Image-Name im YAML</td></tr><tr><td><code>ImagePullBackOff</code> mit „unauthorized“ / „authentication required“</td><td>privates Image ohne oder mit falschem Pull Secret</td><td>Events; <code>imagePullSecrets</code> im Pod; Secrets im Namespace</td></tr><tr><td><code>ImagePullBackOff</code> mit Zeitüberschreitung</td><td>Registry vom Cluster aus nicht erreichbar (Proxy, Firewall)</td><td>Events</td></tr><tr><td><code>CrashLoopBackOff</code>, Log nennt fehlende Variable oder Datei</td><td>Konfiguration fehlt oder heißt anders (ConfigMap, Secret, Variable)</td><td>Log des vorigen Laufs (Konsole: „Previous log“, CLI: <code>--previous</code>); Environment; ConfigMap</td></tr><tr><td><code>CrashLoopBackOff</code>, Log „Permission denied“</td><td>Image erwartet root oder schreibt in nicht beschreibbare Verzeichnisse (OpenShift: zufällige UID)</td><td>Log des vorigen Laufs; Basis-Image</td></tr><tr><td><code>CreateContainerConfigError</code></td><td>referenzierte ConfigMap/Secret fehlt; Sicherheitsregel (z. B. <code>runAsNonRoot</code>) verhindert den Start</td><td>Events</td></tr><tr><td>Letzter Status <code>OOMKilled</code>, Exit-Code 137</td><td>Speicherlimit zu niedrig für die Anwendung</td><td>Details/YAML: Last State; Metrics</td></tr><tr><td>Häufige Neustarts, Events „Liveness probe failed“</td><td>Liveness Probe prüft falschen Pfad/Port oder ist zu streng</td><td>Events; Probe im YAML; Endpunkt im Container aufrufen</td></tr><tr><td><code>Running</code>, aber <code>READY 0/1</code></td><td>Readiness Probe schlägt fehl (falscher Pfad, Anwendung nicht bereit, Abhängigkeit fehlt)</td><td>Events „Readiness probe failed“; Probe im YAML</td></tr><tr><td>Pod hängt in <code>Terminating</code></td><td>Anwendung beendet sich nicht; Finalizer; Node nicht erreichbar</td><td>Events; Details</td></tr></tbody></table><h2 id="erreichbarkeit" tabindex="-1">Erreichbarkeit <a class="header-anchor" href="#erreichbarkeit" aria-label="Permalink to &quot;Erreichbarkeit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Typische Ursachen</th><th>Prüfen</th></tr></thead><tbody><tr><td>Router: 503 „Application is not available“</td><td>Route zeigt auf nicht vorhandenen Service; Service ohne bereite Endpoints</td><td>Route (Ziel-Service); Endpoints des Service; READY der Pods</td></tr><tr><td>Ingress-Controller: 404</td><td>kein Ingress für diesen Host/Pfad; Ingress zeigt auf nicht vorhandenen Service</td><td>Ingress (Host, Backend); Services</td></tr><tr><td>502 sofort</td><td>Ziel weist ab: falscher <code>targetPort</code>, Anwendung lauscht nicht; NetworkPolicy, die abweist</td><td>Service-Ports; Endpoints mit Port; Log des aufrufenden Proxys</td></tr><tr><td>502 mit „could not be resolved“ / „Host not found“</td><td>Service-Name falsch oder ohne Namespace aus einem anderen Namespace aufgerufen</td><td>Konfiguration der Ziel-Adresse; <code>getent hosts &lt;name&gt;</code></td></tr><tr><td>504 nach einigen Sekunden</td><td>Ziel antwortet nicht: NetworkPolicy verwirft Pakete; Ziel überlastet; Firewall</td><td>NetworkPolicies im Ziel-Namespace; Aufruf aus dem Ziel-Namespace selbst</td></tr><tr><td>500</td><td>Fehler in der Anwendung</td><td>Logs, bei Sidecar-Logging das Log des Sidecars</td></tr><tr><td>Fehler nur bei jeder zweiten oder dritten Anfrage</td><td>ein Pod fehlerhaft, aber als bereit gemeldet</td><td>Logs aller Pods vergleichen; antwortenden Pod ermitteln</td></tr><tr><td>Immer derselbe Pod antwortet</td><td>übrige Pods nicht bereit; Sitzungsbindung (Cookie) direkt hinter dem Router</td><td>Endpoints; Aufruf ohne Cookie</td></tr><tr><td>Fehler nur während eines Updates</td><td>fehlende Readiness Probe; Pods erhalten noch Anfragen beim Beenden</td><td>Probes; Verlauf des Rollouts</td></tr></tbody></table><h2 id="externe-systeme" tabindex="-1">Externe Systeme <a class="header-anchor" href="#externe-systeme" aria-label="Permalink to &quot;Externe Systeme&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Typische Ursachen</th><th>Prüfen</th></tr></thead><tbody><tr><td>„Connection refused“ zu einem externen System</td><td>Port geschlossen oder Dienst gestoppt; Firewall weist ab</td><td>Aufruf aus einem Pod im selben Namespace (<code>curl -v</code>); anderer Port desselben Ziels zum Vergleich</td></tr><tr><td>Zeitüberschreitung zu einem externen System</td><td>Firewall verwirft; Routing; Egress-NetworkPolicy</td><td>Aufruf aus einem Pod; NetworkPolicies mit Egress-Regeln</td></tr><tr><td>Name des externen Systems nicht auflösbar</td><td>DNS-Eintrag fehlt oder ist im Cluster nicht sichtbar</td><td><code>getent hosts &lt;name&gt;</code> aus einem Pod</td></tr><tr><td>Zertifikatsfehler zu einem externen System</td><td>eigene oder interne CA im Container nicht vertraut</td><td>Fehlermeldung im Log; CA-Bundle im Image</td></tr></tbody></table><p>Angaben für eine Firewall-Freigabe: <strong>Quelle</strong> (Adresse der Nodes oder Egress-IP des Clusters), <strong>Ziel</strong> (Hostname/Adresse), <strong>Port und Protokoll</strong>, <strong>Richtung</strong>.</p><h2 id="helm" tabindex="-1">Helm <a class="header-anchor" href="#helm" aria-label="Permalink to &quot;Helm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Typische Ursachen</th><th>Prüfen</th></tr></thead><tbody><tr><td>Nach einem Upgrade fehlen eigene Einstellungen</td><td>beim Upgrade andere Werte angegeben (<code>--set</code>, Datei ohne alle eigenen Werte), die die bisherigen ersetzt haben; in der Konsole Werte nach Versionswechsel zurückgesetzt</td><td><code>helm get values</code>; <code>helm history</code></td></tr><tr><td>„another operation is in progress“</td><td>voriges Upgrade abgebrochen, Release in <code>pending-*</code></td><td><code>helm history</code>; Rollback auf letzte erfolgreiche Revision</td></tr><tr><td>Von Hand geänderte Werte sind nach einem Upgrade verschwunden</td><td>Helm setzt den Stand aus Chart und Values durch</td><td>Änderung in die Values-Datei übernehmen</td></tr><tr><td>„resource already exists“ bei der Installation</td><td>Objekt gleichen Namens existiert bereits ohne Helm</td><td>vorhandenes Objekt löschen oder anderen Release-Namen wählen</td></tr><tr><td>Rollback nicht möglich</td><td>keine vorige funktionierende Revision</td><td>Upgrade auf eine funktionierende Version</td></tr></tbody></table>',11)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
